[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$CatalogPath,[string]$SourceId,[string]$PathPattern='*',[string]$Format,[ValidateSet('ready','error')][string]$Status,[string]$HashPrefix,[int]$MaxResults=256)
$ErrorActionPreference='Stop';if($MaxResults -lt 1 -or $MaxResults -gt 4096){throw 'MaxResults must be between 1 and 4096.'};$catalog=Get-Content -LiteralPath $CatalogPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop;if($catalog.catalogId -ne 'es-resource-reader.resource-catalog.v1'){throw 'Unsupported resource catalog.'};$matches=@(@($catalog.items)|Where-Object{($_.sourceId -ieq $SourceId -or [string]::IsNullOrWhiteSpace($SourceId)) -and ($_.sourcePath -like $PathPattern) -and ([string]::IsNullOrWhiteSpace($Format)-or $_.detectedFormat -ieq $Format)-and ([string]::IsNullOrWhiteSpace($Status)-or $_.status -ieq $Status)-and ([string]::IsNullOrWhiteSpace($HashPrefix)-or $_.sourceSha256 -like ($HashPrefix.ToLowerInvariant()+'*'))}|Sort-Object globalKey|Select-Object -First $MaxResults);[ordered]@{schemaVersion=1;queryId='es-resource-reader.catalog-query.v1';catalogPath=(Resolve-Path $CatalogPath).Path;matchedCount=$matches.Count;items=$matches;nonClaims=@('semantic equivalence beyond hash','source freshness beyond catalog capture','Unity import','runtime loading','release readiness')}|ConvertTo-Json -Depth 12
